 @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"none","rule","input","both","manual"})
 void legacyFrozenCdacPreservesResponsibilityWithoutRepeatingCash(String mode){
  var original=legacyCdacNormal(mode);String amount=mode.equals("none")?"0.00":mode.equals("both")?"6.00":"3.00";
  var unknown=settlements().read(admin,store,company,employee,"2026-10").balance();
  assertThat(unknown.cdac().target()).isEqualTo(amount);assertThat(unknown.cdac().recognised()).isEqualTo(amount);
  assertThat(unknown.cdac().deducted()).isNull();assertThat(unknown.cdac().remitted()).isNull();
  evidence("200",amount);
  var payment=proxy(new PayrollPaymentService(access,new PayrollAccess(access,directory,jdbc),new PayrollRepository(jdbc,json),batches(),repository,audit,later));
  payment.register(admin,store,original.batch().id(),UUID.randomUUID(),new PayrollDtos.PaymentWrite(employee,"100",LocalDate.of(2026,11,1),"cash","","original partial payment",null,""));
  String frozen=jdbc.queryForObject("select calculation::text from workforce_pay_batches where id=?",String.class,original.batch().id());
  String profile=json.write(configs.profiles(tenant,company));
  String payments=jdbc.queryForObject("select jsonb_agg(to_jsonb(p) order by id)::text from workforce_pay_payments p where tenant_id=?",String.class,tenant);
  var b=action(draft("101"),"calculate");assertThat(b.batch().calculation().issues()).isEmpty();
  assertThat(b.batch().calculation().cdacDelta()).isEqualTo("0.00");assertThat(b.batch().calculation().cdacDeduction()).isEqualTo("0.00");assertThat(b.batch().calculation().employeeCashPayable()).isEqualTo("80.00");action(b,"confirm");
  var second=action(draft("101"),"calculate");assertThat(second.batch().calculation().issues()).isEmpty();assertThat(second.batch().calculation().cdacDelta()).isEqualTo("0.00");assertThat(second.batch().calculation().cdacDeduction()).isEqualTo("0.00");action(second,"confirm");
  var after=settlements().read(admin,store,company,employee,"2026-10").balance();assertThat(after.cdac().target()).isEqualTo(amount);assertThat(after.cdac().recognised()).isEqualTo(amount);assertThat(after.cdac().deducted()).isEqualTo(amount);
  assertThat(jdbc.queryForObject("select calculation::text from workforce_pay_batches where id=?",String.class,original.batch().id())).isEqualTo(frozen);
  assertThat(json.write(configs.profiles(tenant,company))).isEqualTo(profile);
  assertThat(jdbc.queryForObject("select jsonb_agg(to_jsonb(p) order by id)::text from workforce_pay_payments p where tenant_id=?",String.class,tenant)).isEqualTo(payments);
 }
 @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"missing-components","empty-components","missing-item","invalid-amount","review-null","review-manual"})
 void legacyIncompleteOrInvalidCdacStaysUnknownAndBlocksConfirmation(String defect)throws Exception{
  var original=legacyCdacNormal(defect.equals("review-manual")?"manual":"rule");
  // Synthetic historical fixture only: install the incomplete/invalid old JSON before preservation assertions.
  var mapper=new com.fasterxml.jackson.databind.ObjectMapper();var snapshot=mapper.readTree(json.write(original.calculation()));var line=(com.fasterxml.jackson.databind.node.ObjectNode)snapshot.path("lines").get(0);
  var components=(com.fasterxml.jackson.databind.node.ArrayNode)line.get("components");
  switch(defect){case "missing-components"->line.remove("components");case "empty-components"->components.removeAll();case "missing-item"->{for(int i=components.size()-1;i>=0;i--)if(components.get(i).path("kind").asText().equals("cdac"))components.remove(i);}case "invalid-amount"->{for(var c:components)if(c.path("kind").asText().equals("cdac"))((com.fasterxml.jackson.databind.node.ObjectNode)c).put("amount","invalid");}default->((com.fasterxml.jackson.databind.node.ObjectNode)line.get("input")).set("cdacReview",mapper.readTree("{\"amount\":\"3\",\"note\":\"illegal legacy review\"}"));}
  jdbc.update("update workforce_pay_batches set calculation=?::jsonb where tenant_id=? and id=?",snapshot.toString(),tenant,original.batch().id());
  String frozen=jdbc.queryForObject("select calculation::text from workforce_pay_batches where id=?",String.class,original.batch().id());evidence("200","3");
  var balance=settlements().read(admin,store,company,employee,"2026-10").balance();assertThat(balance.cdac().target()).isNull();assertThat(balance.cdac().recognised()).isNull();assertThat(balance.issues()).contains(defect.startsWith("review-")?"CDAC_REVIEW_INVALID":"CDAC_ORIGINAL_LIABILITY_MISSING");
  var b=action(draft("101"),"calculate");assertThat(b.batch().calculation().cdacDelta()).isNull();assertThat(b.batch().calculation().employeeCashPayable()).isNull();assertThatThrownBy(()->action(b,"confirm")).hasMessage("STATUTORY_SETTLEMENT_BLOCKED");
  assertThat(jdbc.queryForObject("select calculation::text from workforce_pay_batches where id=?",String.class,original.batch().id())).isEqualTo(frozen);
 }
 PayrollDtos.BatchDetail legacyCdacNormal(String mode){
  var p=personal(0,"1004").profile();var item=new PayrollDtos.Item("Legacy fixed CDAC","cdac","3.00");
  var recurring=Set.of("rule","both","manual").contains(mode)?List.of(item):List.<PayrollDtos.Item>of();var monthly=Set.of("input","both").contains(mode)?List.of(new PayChangeDtos.MonthWrite("2026-10",new PayrollDtos.InputWrite(0L,null,null,true,false,List.of(item),"original monthly CDAC"))):List.<PayChangeDtos.MonthWrite>of();
  var rule=new PayrollDtos.Rule("monthly","1004","8","44",false,"1.5",recurring,new PayrollDtos.Generation("fixed",List.of()));
  approve(submit(changes.save(admin,store,UUID.randomUUID(),new PayChangeDtos.Write(0L,company,employee,LocalDate.of(2026,10,1),null,new PayrollDtos.ProfileWrite(0L,company,employee,LocalDate.of(2026,10,1),p.templateId(),rule,new StatutoryDtos.CpfProfile("citizen",LocalDate.of(1990,1,1),null,"GG",""),null,Set.of("manual","none","input").contains(mode)?new PayrollDtos.CdacProfile("manual","original manual setting"):null),monthly,null,"original legacy contract"))));
  var service=batches();var b=calculated(service);assertThat(b.calculation().issues()).isEmpty();b=service.action(admin,store,b.batch().id(),UUID.randomUUID(),new PayrollDtos.ActionWrite(b.batch().version(),"confirm","original"));b=service.action(admin,store,b.batch().id(),UUID.randomUUID(),new PayrollDtos.ActionWrite(b.batch().version(),"publish","original"));
  // Today's declaration guard is retained. Represent a pre-declaration snapshot only in this random test schema.
  if(Set.of("none","input").contains(mode))jdbc.update("update workforce_pay_batches set calculation=(calculation #- '{lines,0,profile,cdac}') #- '{lines,0,cdacCalculation}' where tenant_id=? and id=?",tenant,b.batch().id());
  return service.detail(admin,store,b.batch().id());
 }
