 void originalPaymentRace(boolean reversing)throws Exception{var original=normal("1004");evidence("200","0.50");var payment=proxy(new PayrollPaymentService(access,new PayrollAccess(access,directory,jdbc),new PayrollRepository(jdbc,json),batches(),repository,audit,later));UUID prior=UUID.randomUUID();if(reversing)payment.register(admin,store,original.batch().id(),prior,new PayrollDtos.PaymentWrite(employee,"100",LocalDate.of(2026,11,1),"cash","","original payment",null,""));var b=action(draft("101"),"calculate");assertThat(b.batch().calculation().issues()).isEmpty();var written=new CountDownLatch(1);var release=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var writer=pool.submit(()->new org.springframework.transaction.support.TransactionTemplate(tx).execute(status->{var response=payment.register(admin,store,original.batch().id(),UUID.randomUUID(),new PayrollDtos.PaymentWrite(employee,"100",LocalDate.of(2026,11,1),"cash","","original partial wage",reversing?prior:null,""));written.countDown();try{if(!release.await(15,TimeUnit.SECONDS))throw new IllegalStateException("timeout");}catch(InterruptedException e){throw new IllegalStateException(e);}return response;}));assertThat(written.await(15,TimeUnit.SECONDS)).isTrue();var confirming=pool.submit(()->{try{action(b,"confirm");return "confirmed";}catch(com.rpb.reservation.workforce.domain.WorkforceException e){return e.code();}});String key="workforce.payroll.source:"+tenant;long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);boolean waiting=false;while(System.nanoTime()<deadline){if(jdbc.queryForObject("select count(*) from pg_locks where locktype='advisory' and not granted and mode='ExclusiveLock' and classid::bigint=((hashtextextended(?,0)>>32)&4294967295) and objid::bigint=(hashtextextended(?,0)&4294967295)",Integer.class,key,key)>0){waiting=true;break;}Thread.sleep(20);}assertThat(waiting).isTrue();release.countDown();writer.get(20,TimeUnit.SECONDS);assertThat(confirming.get(20,TimeUnit.SECONDS)).isEqualTo("SUPPLEMENTAL_SOURCE_CHANGED");assertThat(jdbc.queryForObject("select count(*) from workforce_wage_event_consumptions where tenant_id=?",Integer.class,tenant)).isZero();}finally{release.countDown();pool.shutdownNow();}}
